`function Cari(const a: array of Integer; target: Integer): Integer;
var lo, hi, mid: Integer;
begin
  lo := 0; hi := High(a);
  while lo <= hi do
  begin
    mid := (lo + hi) div 2;
    if a[mid] = target then Exit(mid)
    else if a[mid] < target then lo := mid + 1
    else hi := mid - 1;
  end;
  Result := -1;
end;` (!) — sorted input required (!) — O(log n) (!).

